const fs = require('fs');
const path = require('path');

function createEnvironmentConfig() {
  try {
    console.log('Creating environment configuration...');
    
    // Generate environment config for production
    const envConfig = {
      FORMSPREE_ENDPOINT: process.env.FORMSPREE_ENDPOINT || '',
      GITHUB_TOKEN: process.env.GITHUB_TOKEN || '',
    };
    
    const envConfigPath = path.join(__dirname, '../../js/env-config.js');
    const envConfigContent = `// Auto-generated environment configuration
// This file is generated by GitHub Actions and contains environment variables
window.ENV_CONFIG = ${JSON.stringify(envConfig, null, 2)};
`;
    
    fs.writeFileSync(envConfigPath, envConfigContent);
    console.log(`Environment config written to ${envConfigPath}`);
    
  } catch (error) {
    console.error('Error creating environment config:', error);
    process.exit(1);
  }
}

// Run the script
createEnvironmentConfig();
